  }

  const deleteTx = (t: Transaction) => {
    const label = `${t.type} of ${formatCents(t.amountCents)}${t.note ? ` (“${t.note}”)` : ''}`
    const series = t.recurringId && data.recurring.some((r) => r.id === t.recurringId)
