                onDelete={(id) => {
                  setData((d) => ({
                    categories: d.categories.filter((c) => c.id !== id),
                    transactions: d.transactions.map((t) => (t.categoryId === id ? { ...t, categoryId: 'other' } : t)),
                    version: 1,
                  }))
                  if (filters.categoryId === id) setFilters((f) => ({ ...f, categoryId: '' }))
                }}
              />
            </div>

